def put_layout(%Plug.Conn{state: state} = conn, layout) do
    if state in @unsent do
      put_private_layout(conn, :phoenix_layout, :replace, layout)
    else
      raise AlreadySentError, """
      the response was already sent.

          Status code: #{conn.status}
          Request path: #{conn.request_path}
          Method: #{conn.method}
          Layout: #{inspect(layout)}
      """
    end
  end

def put_new_layout(%Plug.Conn{state: state} = conn, layout)
      when (is_tuple(layout) and tuple_size(layout) == 2) or is_list(layout) or layout == false do
    unless state in @unsent do
      raise(AlreadySentError, """
      the response was already sent.

          Status code: #{conn.status}
          Request path: #{conn.request_path}
          Method: #{conn.method}
          Layout: #{inspect(layout)}
      """)
    end

    put_private_layout(conn, :phoenix_layout, :new, layout)
  end

def put_root_layout(%Plug.Conn{state: state} = conn, layout) do
    if state in @unsent do
      put_private_layout(conn, :phoenix_root_layout, :replace, layout)
    else
      raise AlreadySentError, """
      the response was already sent.

          Status code: #{conn.status}
          Request path: #{conn.request_path}
          Method: #{conn.method}
          Layout: #{inspect(layout)}
      """
    end
  end

def socket(channel_pid) do
    if channel_process?(channel_pid) do
      {:ok, Phoenix.Channel.Server.socket(channel_pid)}
    else
      {:error, :not_alive_or_not_a_channel}
    end
  catch
    :exit, _ -> {:error, :not_alive_or_not_a_channel}
  end

def connect_info(conn, endpoint, keys, opts \\ []) do
    for key <- keys, into: %{} do
      case key do
        :peer_data ->
          {:peer_data, Plug.Conn.get_peer_data(conn)}

        :trace_context_headers ->
          {:trace_context_headers, fetch_trace_context_headers(conn)}

        :x_headers ->
          {:x_headers, fetch_headers(conn, "x-")}

        :uri ->
          {:uri, fetch_uri(conn)}

        :user_agent ->
          {:user_agent, fetch_user_agent(conn)}

        :sec_websocket_headers ->
          {:sec_websocket_headers, fetch_headers(conn, "sec-websocket-")}

        {:session, session} ->
          {:session, connect_session(conn, endpoint, session, opts)}

        :auth_token ->
          {:auth_token, conn.private[:phoenix_transport_auth_token]}

        {key, val} ->
          {key, val}
      end
    end
  end
